function matchBlog(url) {
  // app/blog/[slug]
  const m = url.match(/^\/blog\/([^/]+)$/);
  return m ? { slug: m[1] } : null;
}
function matchDocs(url) {
  // app/docs/[...slug]
  const m = url.match(/^\/docs\/(.+)$/);
  return m ? { slug: m[1].split('/') } : null;
}
function App() {
  const urls = ['/blog/hello', '/docs/a/b/c', '/docs/intro'];
  return (
    <div style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 13 }}>
      {urls.map(u => {
        const params = matchBlog(u) || matchDocs(u);
        return <div key={u}>{u} -> params = {JSON.stringify(params)}</div>;
      })}
    </div>
  );
}

