solution.code:
function Page({ params }) {
  const segments = params.slug ?? []; // optional catch-all may be undefined
  const last = segments[segments.length - 1] ?? 'index';
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <h1>{last.toUpperCase()}</h1>
      <p>path: /{segments.join('/')}</p>
    </div>
  );
}
const params = { slug: ['guide', 'setup'] };
function App() { return <Page params={params} />; }

// app/blog/[slug]/page.tsx (Server Component)
import { notFound } from 'next/navigation';

export const dynamicParams = false; // 404 any slug not pre-built
export const revalidate = 3600;     // ISR: refresh hourly

export async function generateStaticParams() {
  const posts = await getPosts();
  return posts.map((p) => ({ slug: p.slug }));
}

type Props = {
  params: { slug: string };
  searchParams: { [key: string]: string | string[] | undefined };
};

export default async function BlogPost({ params, searchParams }: Props) {
  const post = await getPost(params.slug);
  if (!post) notFound();

  const showComments = searchParams.comments === '1';
  return (
    <article>
      <h1>{post.title}</h1>
      <p>{post.body}</p>
      {showComments && <Comments slug={params.slug} />}
    </article>
  );
}
